{"entry_id": 838110, "dictionary_id": 125, "headword": "شرس", "headword_bare": "شرس", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "باب الشين والسين والراء معهما ش ر س مستعمل فقط\nشرس: الشرس: شبه الدعك، كما يشرس الحمار ظهور العانة بلحييه، ونحو ذلك. وقيل: الشرس: النهس، وهو عضيض الحمار والفرس، الذي لا يقطع، وهو أوضع من القطع أو مثله، قال:\nقدا بأنياب وشرساً أشرسا \nرجل شرس الخلق، وإنه لأشرس، وإنه لشريس، أي: عسر شديد الخلاف، قال: فظلت ولي نفسان نفس شريسة ... ونفس تعناها الفراق جزوع \nوالشراس: شدة المشارسة في معاملة الناس. رجل أشرس ذو شراس، وناقة شريسة، قال:\nقد علمت عمرة بالغميس ... أن أبا المسور ذو شريس\nوأمكنه شراس، أي: صلبة خشنة، وأرض شرساء. وشراس: نعت واجب على فعال.", "translation_en": null, "domain": null, "dict_key": "hawramani_3", "dict_name_ar": "كتاب العين للخليل بن أحمد الفراهيدي", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 786}
{"entry_id": 981844, "dictionary_id": 150, "headword": "شرس", "headword_bare": "شرس", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "[شرس] رَجُلٌ شَرِسٌ، أي سَيئُ الخلق بيّن الشَرَسِ والشَراسَةِ. وهو شرس وأشرس، أي عسير شديد الخلاف. وتَشارَسَ القومُ، أي تَعادَوا. ومكان شرس، أي غليظ. قال الراجز  إذا أنيخت بمكان شرس * خرت على مستويات خمس * كركرة وثفنات ملس * والشرس بالكسر: عِضاهُ الجَبَلِ، وهو ما صَغُر من شجر الشوك كالشُبْرُمِ والحاج. وبنو فلان مُشْرِسونَ، أي ترعى إبلُهم الشِرْسَ. وأرضٌ مُشْرسَةٌ: كثيرة الشرس، عن يعقوب.", "translation_en": null, "domain": null, "dict_key": "hawramani_6", "dict_name_ar": "تاج اللغة وصِحاح العربية للجوهري", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 1003}
{"entry_id": 987136, "dictionary_id": 151, "headword": "شَرَسَ ", "headword_bare": "شرس ", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "(شَرَسَ) الشِّينُ وَالرَّاءُ وَالسِّينُ أَصْلٌ قَرِيبٌ مِنَ الَّذِي قَبْلَهُ. مِنْ ذَلِكَ الشَّرْسُ: شِدَّةُ الدَّعْكِ لِلشَّيْءِ. يُقَالُ: شَرَسْتُهُ شَرْسًا. وَالشَّرِيسُ: الشَّكِسُ الْكَثِيرُ الْخِلَافِ. وَيُقَالُ: تَشَارَسَ الْقَوْمُ، إِذَا تَعَادَوْا. وَيُقَالُ: إِنَّ الشِّرْسَ نَبْتٌ بَشِعُ الطَّعْمِ. وَالْأَشْرَسُ: الرَّجُلُ الْجَرِيءُ عَلَى الْقِتَالِ. وَيُقَالُ: إِنَّ الشِّرَاسَ الرِّبَاقُ.", "translation_en": null, "domain": null, "dict_key": "hawramani_7", "dict_name_ar": "مقاييس اللغة لابن فارس", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 1004}
{"entry_id": 992726, "dictionary_id": 152, "headword": "شرس", "headword_bare": "شرس", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "الشين والسين والراء ش ر س\nرَجُلٌ شَرِسٌ وشَرِيسٌ وأَشْرَسٌ عَسِرُ الخُلُقِ وقد شَرِسَ شَرَسًا وشَرَاسَةً وفيه شِرَاسٌ وشَرِسَت نَفْسُه شَرَسًا وشَرُسَتْ شَرَاسَةً فهي شَرِيسَةٌ قالَ\n(فَرُحْتُ ولِي نَفْسانِ نَفْسٌ شَرِيسَةٌ ... وَنَفْسٌ تَعَنَّاهَا الفِراقُ جَزُوعُ)\nوَشَارَسَهُ مُشَارَسَةً وَشِرَاسًا عَاسَرَهُ وَشَاكَسَهُ ونَاقَةٌ شَرِيسَة بَيِّنَةُ الشِّراسِ سَيِّئَةُ الخُلُقِ وإنَّه لذُو شَرِيسٍ أي عُسْر قال\n(قَدْ عَلِمَتْ عَمْرةُ بالغَمِيسِ ... أنَّ أَبا المِسْوارِ ذُو شَرِيسِ)\nوَتَشَارَسَ الْقَوْمُ تَعَادَواْ والشَّرْسُ شِدَّةُ وَعْكِ الشَّيءِ شَرَسَه يَشْرُسُهُ شَرْسًا وشَرَسَ الحِمَارُ أُتُنَهُ يَشْرُسُها شَرْسًا أَمَرَّ لَحْيَيْهِ وَنَحْوَ ذَلِكَ عَلَى طُهُورِها وَمَكانٌ شِرَاسٌ خَشِنُ الْمَسِّ وأَرْضٌ شَرْساءُ وشَرَاسِ عَلَى مِثَالِ قَطَامِ خَشِنةٌ غَلِيظةٌ وقال أَبُو حَنِيفَةَ شَرَسَتِ الماشِيةُ تَشْرُسُ شَرَاسَةً اشتدّ أَكْلُها وإِنِّه لَشَرِيسُ الأَكْلِ أي شدِيدُه والشَّرِيسُ نبتٌ بَشِعُ الطَّعمِ وقيل كلُّ بَشِعِ الطَّعْمِ شَرِيسٌ والشَّرْسُ عِضَاهُ الجَبَلِ وله شَوْكٌ أصْفَرُ وقيل الشِّرْسُ مَا رَقَّ شَوْكُه مِنَ العِضاهِ ونَبَاتُه الهُجُول والصَّحَارَى ولا يَنْبُتُ في الجَرَعِ ولا قِيعانِ الأَوْدِيَةِ وقيل الشِّرَس شَجَرٌ صِغَارٌ له شَوْكٌ وقيل الشِّرْسُ حَمْلُ نَبْتٍ مَا وأَشْرَسَ القوْمُ رَعَتْ إِبلُهُم الشِّرْسَ وأرضٌ مُشْرِسَةٌ وشَرِيسَة كَثيرةُ الشَّرَسِ والشَّرَسُ بفَتْح الشينِ والرَّاء ما صَغُرَ من شَجَرِ الشَّوْكِ حكاه أبو حَنيفةَ وأَشْرَسُ وشَرِيسٌ اسْمانِ", "translation_en": null, "domain": null, "dict_key": "hawramani_8", "dict_name_ar": "المحكم والمحيط الأعظم لابن سيده الأندلسي", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 1066}
{"entry_id": 998162, "dictionary_id": 153, "headword": "شرس", "headword_bare": "شرس", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "ش ر س\nفيه شكاسة وشراسة، وهو عسر شرس. ومارسه فشارسه، وهو ذو شراس وشريس، وقد لان شريسه. قال:\nقد علمت عمرة بالغميس ... أن أبا المسوار ذو شريس\nوله نفس شريسة: قال:\nفظلت ولي نفسان نفس شريسة ... ونفس تعنّاها الفراق جزوع", "translation_en": null, "domain": null, "dict_key": "hawramani_9", "dict_name_ar": "أساس البلاغة للزمخشري", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 1143}
{"entry_id": 780561, "dictionary_id": 105, "headword": "شَرَسَ", "headword_bare": "شرس", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "(شَرَسَ)(هـ) فِي حَدِيثِ عَمْرِو بْنِ مَعْدِ يكَرِب «هُمْ أعظمُنا خَمِيساً وَأَشَدُّنَا شَرِيساً» أَيْ شَرَاسَةً. وَقَدْ شَرِسَ يَشْرَسُ فَهُوَ شَرِسٌ. وَقَوْمٌ فِيهِمْ شَرَسٌ وشَرِيسٌ وشَرَاسَةٌ: أَيْ نُفُور وسوءُ خُلُق. وَقَدْ تَكَرَّرَ فِي الْحَدِيثِ.", "translation_en": null, "domain": null, "dict_key": "hawramani_11", "dict_name_ar": "النهاية في غريب الحديث والأثر لأبي السعادات ابن الأثير الجزري", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 1210}
{"entry_id": 784021, "dictionary_id": 106, "headword": "شرس", "headword_bare": "شرس", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "(ش ر س) : (الشِّرْسُ) مَا صَغُرَ مِنْ الشَّوْكِ.", "translation_en": null, "domain": null, "dict_key": "hawramani_12", "dict_name_ar": "المغرب في ترتيب المعرب للمُطَرِّزي", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 1213}
{"entry_id": 785892, "dictionary_id": 107, "headword": "شرس", "headword_bare": "شرس", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "(شرس) : الشُّرْسُ: الجَرَب في مَشافِرِ الناقَةِ، وناقَةٌ مَشْرُوسَةٌ.الشَّلِيلُ: الجَهامُ، قال صالح:إنَّا لنَقْرِى يا عُمَيْرَ ضُيُوفَنا ... وَيكُونُ أَوّلَ ما قَرَيْنَا المَرْحَبُ شَحْمَ السَّنام إذا الصَّبا أَمْسَتْ صَبأ ... صَهْباءَ يْطرُدُها شَلِيلُ العَقْربِيَكْسُو البُيوتَ من الجَلِيدِ أَمالِحاً ... سَبَق الذِّراعَ به نَفِيُّ الكَوْكَبِ", "translation_en": null, "domain": null, "dict_key": "hawramani_13", "dict_name_ar": "الشوارد للصغاني", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 1252}
{"entry_id": 909728, "dictionary_id": 133, "headword": "شرس", "headword_bare": "شرس", "headword_norm": "شرس", "root": "شرس", "root_source": "camel", "pos": null, "definitions_text": "شرسرَجُلٌ أشْرَسُ وشَرِسٌ بَيِّنُ الشَّرَسِ والشَّرَاسَةِ: أي سَيِّئُ الخُلُقِ عَسِرٌ شَديدُ الخِلافِ، وأنشد الليث:فَظَلْتُ ولي نَفْسانِ نَفْسٌ شَرِيْسَةٌ ... ونَفْسٌ تَعَنّاها الفِراقُ جَزُوْعُوالأشْرَسُ: الجريء في القتال.والأشْرَسُ والشَّرِسُ: الأسد، سمِّيَ بذلك لسوءِ خُلُقِه، قال أبو زبَيْد حَرْمَلة بن المنذر الطائي يصف الأسد:جَهْمَ المُحَيّا عَبُوْساً ضَيْغَماً شَرِساً ... ما إنْ يَطُوْرُ حِماهُ غَيْرُ مَعْرُورِوأشْرَسُ بن غاضِرَةَ - رضي الله عنه -: له صحبة.وأرضٌ شَرْساء وشَرَاسٍ - على فَعَالٍ - مثال شَنَاحٍ ورَبَاعٍ وحَزَابٍ وشَرَاسٌ - مثال سَراب وزَمان ومَكان -:غليظة.والشِّرَاسُ - بالكسر -: دِباقُ الأساكِفَةِ، ويكْتُبُونَه في كُتُبِ الطِّبِّ: إشْرَاسٌ.والشَّريس: الشَّراسَة. ومنه حديث عمر - رضي الله عنه - أنَّه قال لعمرو بن معدي كَرِب - رضي الله عنه -: ما قَولُك في عُلَة بن جَلدٍ؟ قال: أولئك فوارِسُ أعراضِنا وشِفاءُ أمراضِنا؛ أحَثُّنا طَلَباً وأقَلُّنا هَرَباً، قال: فَسَعْدُ العشيرَة؟ قال: أعظمُنا خَميساً وأكثرُنا رئيساً وأشدُّنا شَرِيساً، قال: فبنو الحَرثِ؟ قال: حَسَكَة مَسَكَة، قال: فَمُراد؟ قال: أولئك الأتقياء البَرَرَة والمَسَاعير الفَخَرَة؛ أكرمنا قراراً وأبعَدُنا آثاراً.وناقةُ ذات شَرِيس: أي شَرِسَة، قال:قد عَلِمَت عَمْرَةُ بالغَمِيْسِ ... أنَّ أبا المِسْوَرِ ذو شَرِيْسِولانَ شَرِيسُه: كقولِهِم لانَت عَريكَتُه.والشَّرْس: جَذْبُكَ الناقة بالزِّمام. وقال ابن عبّاد: شَرَسْتُ الجِلْدَ والرّاحِلَة: إذا مَرَسْتُهما، وكذلك الرجل إذا أمَضَّكَ بالكلام.ولم يُشْرَسْ جَمَلُه: أي لم يُرَضْ ولم يُهَنْ.والشِّرْسُ - بالكسر -: عِضَاهُ الجبل، وهو ما صَغُرَ من شَجَر الشَّوْكِ، كالشُّبْرُم والحاجِ والشُّكَاعى والقَتَادِ، وأنشد ابن الأعرابي:واضِعَةٌ تأكُلُ كُلَّ شِرْسِومكان شَرْس - بالفتح -: أي غليظ، قال:إذا أُنيخَت بِمَكانٍ شَرْسِوقال الدِّيْنَوَريّ: الشَّرَسُ - بالتحريك -: ما صَغُرَ من شَجَر الشَّوْكِ. قال: ومن أمثال العَرَب: عثرَ بأشْرَس الدَّهر: أي بالشِّدَّة.والشَّرْساء: السحابة الرقيقة البيضاء.وقال ابن الأعرابي: شَرِسَ - بالكسر -: إذا تَحَبَّبَ إلى الناس.وشَرِسَ: إذا دام على رعي الشِّرْسِ.وقال أبو عمرو: الشُّرْسُ - بالضم -: الجَرَبُ في مشافِرِ الأبِل، وإبلٌ مَشروسَة.وقال أبو زيد: الشَّراسَة: شِدَّة أكل الماشِيَة، يقال منه: شَرَسَتْ تَشْرُسُ شَرَاسَة، وانَّه لَشَرِس الأكل.والمُشَارَسَة والشِّرَاسُ: الشِّدَّة في معاملة الناس، يقال: ناقةٌ ذات شِراس.وقال ابن فارِس: تَشَارَسَ القَوْمُ: إذا تَعَادَوا.والتركيب يدل على خِلاف الخَير في جميع فُروعِه.", "translation_en": null, "domain": null, "dict_key": "hawramani_37", "dict_name_ar": "العباب الزاخر للصغاني", "dict_source_type": "hawramani", "dict_period": "classical", "dict_author": null, "dict_death_year": 1252}
